'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let pos = 0;
const N = input[pos++];
const M = input[pos++];
const C = input[pos++];

const earliestDetester = new Int32Array(M + 1);
const favorite = new Int32Array(N + 1);

for (let i = 1; i <= N; i++) {
  const A = input[pos++];
  const D = input[pos++];
  favorite[i] = A;
  if (earliestDetester[D] === 0) earliestDetester[D] = i;
}

const visited = new Uint8Array(M + 1);
let song = C;
let swaps = 0;

while (earliestDetester[song] !== 0) {
  if (visited[song]) {
    console.log(-1);
    process.exit(0);
  }

  visited[song] = 1;
  song = favorite[earliestDetester[song]];
  swaps++;
}

console.log(swaps);
